# OWNER: P4 -- see docs/WORK.md. Do not edit if you are not P4.
"""Every figure in docs/RESULTS.md, redrawn from the summary CSVs.

    python -m experiments.plots                       # results/ -> docs/
    python -m experiments.plots --results-dir /tmp/run

One figure per measurement, each drawn from its `<name>_summary.csv` and
nothing else -- no number in a figure or its table is typed by hand, so a
figure cannot drift from the run it claims to show. The provenance line under
each one (CSV path, git SHA, date, network) is read from that CSV's own `run_*`
columns, not from the checkout doing the plotting.

docs/RESULTS.md is part hand-written. Only the block between `BEGIN` and `END`
is rewritten; the prose around it is left alone. A measurement whose CSV is
not there is listed as not run, with the command that produces it, and its
figure is not redrawn.
"""
from __future__ import annotations

import argparse
import csv
import sys
from collections.abc import Callable, Mapping, Sequence
from dataclasses import dataclass
from pathlib import Path

from experiments import harness
from experiments.svg import Series, bar_chart, line_chart, range_chart

DOCS_DIR: Path = Path(__file__).resolve().parent.parent / "docs"
BEGIN = "<!-- figures:begin -->"
END = "<!-- figures:end -->"
NOTICE = ("*Generated by `python -m experiments.plots` from the summary CSVs named under "
          "each figure. Edit the code, not this block: it is rewritten on every run.*")

Row = Mapping[str, str]
Table = tuple[Sequence[str], Sequence[Sequence[str]]]


def _num(value: str | float) -> str:
    """Table formatting: three significant figures, thousands written out."""
    v = float(value)
    if v == 0:
        return "0"
    return f"{v:,.0f}" if abs(v) >= 1000 else f"{v:.3g}"


def _pct(v: float) -> str:
    return f"{v * 100:.0f}%"


def _ms(v: float) -> str:
    return f"{v:.3g} ms"


# --- one function per measurement: rows in, (svg, table) out ----------------

def _transport(rows: Sequence[Row], caption: str) -> tuple[str, Table]:
    svg = range_chart(
        title="Time to hand off one signed envelope",
        subtitle="send() entry to return, median and p95 per message. Log scale.",
        caption=caption,
        categories=[r["condition"] for r in rows],
        low=Series("median", [float(r["accept_ms_median"]) for r in rows]),
        high=Series("p95", [float(r["accept_ms_p95"]) for r in rows]),
        unit=_ms,
    )
    table = (("condition", "messages", "median ms", "p95 ms", "p95 / median",
              "retries / 100", "lost"),
             [(r["condition"], r["n_messages"], _num(r["accept_ms_median"]),
               _num(r["accept_ms_p95"]), _num(r["p95_over_median"]),
               _num(r["retries_per_100"]), r["messages_lost"]) for r in rows])
    return svg, table


def _topology(rows: Sequence[Row], caption: str) -> tuple[str, Table]:
    wire = rows[0]["transport"]  # the counts do not depend on the wire; wall clock does
    drawn = [r for r in rows if r["transport"] == wire]
    nodes = sorted({int(r["n_nodes"]) for r in drawn})
    shapes = list(dict.fromkeys(r["shape"] for r in drawn))
    by = {(r["shape"], int(r["n_nodes"])): r for r in drawn}

    def at(shape: str, n: int) -> float | None:
        r = by.get((shape, n))
        return float(r["messages_median"]) if r else None

    svg = line_chart(
        title="Messages to finish one task, by topology",
        subtitle=(f"Median per task on {wire}, until every peer holds every result. "
                  f"{len(nodes)} points per shape: the lines join them, they are not a fit."),
        caption=caption,
        x=nodes, x_label="peers (N)",
        series=[Series(s, [at(s, n) for n in nodes]) for s in shapes],
    )
    table = (("transport", "shape", "N", "done", "messages", "theory", "hops", "theory",
              "wall median ms", "wall p95 ms"),
             [(r["transport"], r["shape"], r["n_nodes"], f"{r['n_completed']}/{r['n_tasks']}",
               _num(r["messages_median"]), r["theory_messages"],
               _num(r["hops_median"]) if r["hops_median"] else "--", r["theory_hops"],
               _num(r["wall_ms_median"]) if r["wall_ms_median"] else "--",
               _num(r["wall_ms_p95"]) if r["wall_ms_p95"] else "--") for r in rows])
    return svg, table


def _grounding(rows: Sequence[Row], caption: str) -> tuple[str, Table]:
    shown = [r for r in rows if r["breakdown"] in ("overall", "role")]
    svg = bar_chart(
        title="Grounded claims, direct and through peer_report chains",
        subtitle="Share of claims whose evidence is a test run or a file read",
        caption=caption,
        categories=[r["key"] for r in shown],
        series=[Series("direct", [float(r["grounded_ratio"]) for r in shown]),
                Series("transitive", [float(r["grounded_ratio_transitive"]) for r in shown])],
        unit=_pct, x_max=1.0,
    )
    table = (("by", "claims", "direct", "transitive", "laundered", "model prior"),
             [(f"{r['breakdown']}: {r['key']}", r["total_claims"],
               _pct(float(r["grounded_ratio"])), _pct(float(r["grounded_ratio_transitive"])),
               _pct(float(r["laundered_ratio"])), _pct(float(r["model_prior_ratio"])))
              for r in rows])
    return svg, table


#: (label, column) -- medians per task, each indexed to the inline condition.
_DEDUP = (
    ("input tokens", "input_tokens_median"),
    ("receiver peak context", "peak_context_receiver_median"),
    ("bytes on wire", "bytes_on_wire_median"),
    ("cost (USD)", "usd_median"),
)


def _context_dedup(rows: Sequence[Row], caption: str) -> tuple[str, Table]:
    by = {r["condition"]: r for r in rows}
    inline, refs = by["inline"], by["refs"]
    ratios = [float(refs[c]) / float(inline[c]) if float(inline[c]) else None
              for _, c in _DEDUP]
    svg = bar_chart(
        title="What passing artifacts by ref saves",
        subtitle="Median per task under refs, as a share of the same median inline",
        caption=caption,
        categories=[label for label, _ in _DEDUP],
        series=[Series("refs", ratios)],
        unit=_pct, reference=(1.0, "inline = 100%"),
    )
    table = (("median per task", "inline", "refs", "refs / inline"),
             [(label, _num(inline[c]), _num(refs[c]), _pct(r) if r is not None else "--")
              for (label, c), r in zip(_DEDUP, ratios)])
    return svg, table


def _rate_or_none(value: str) -> float | None:
    """A summary rate; an empty cell is a zero denominator, drawn as no bar."""
    return float(value) if value != "" else None


def _rate_cell(value: str) -> str:
    return _pct(float(value)) if value != "" else "--"


def _disagreement(rows: Sequence[Row], caption: str) -> tuple[str, Table]:
    mock = any(r["mock"] == "1" for r in rows)
    svg = bar_chart(
        title="Bad code the reviewer let through" + (" — MOCK, not a result" if mock else ""),
        subtitle=("Canned replies, no model ran: this checks the pipeline and says nothing "
                  "about models." if mock else
                  "False accepts over code that failed its held-out tests, per pair."),
        caption=caption,
        categories=[r["condition"] for r in rows],
        series=[Series("reviewer alone", [_rate_or_none(r["false_accept_rate"]) for r in rows]),
                Series("after the runtime arbiter",
                       [_rate_or_none(r["arbitrated_false_accept_rate"]) for r in rows])],
        unit=_pct, x_max=1.0,
    )
    table = (("pair", "executor → reviewer", "reviews", "errors", "bad code", "caught",
              "false accept", "false reject", "arbitrated false accept", "unparsed", "mock"),
             [(r["condition"], f"{r['executor']} → {r['reviewer']}", r["n_tasks"], r["n_errors"],
               r["n_bad"], _rate_cell(r["catch_rate"]), _rate_cell(r["false_accept_rate"]),
               _rate_cell(r["false_reject_rate"]), _rate_cell(r["arbitrated_false_accept_rate"]),
               r["n_review_unparsed"], "yes" if r["mock"] == "1" else "no") for r in rows])
    return svg, table


@dataclass(frozen=True)
class Figure:
    name: str                 # docs/figures/<name>.svg
    heading: str
    csv: str                  # results/<csv>.csv
    command: str              # what produces the CSV
    draw: Callable[[Sequence[Row], str], tuple[str, Table]]


FIGURES: tuple[Figure, ...] = (
    Figure("transport", "1 — Transport comparison", "transport_summary",
           "python -m experiments.transport --conditions inproc,loopback", _transport),
    Figure("topology", "2 — Message complexity by topology", "topology_summary",
           "python -m experiments.topology --nodes 4 --shape star,ring,mesh", _topology),
    Figure("grounding", "3 — Grounded-claim ratio", "grounding_summary",
           "python -m experiments.grounding", _grounding),
    Figure("context_dedup", "4 — Context dedup effect", "context_dedup_summary",
           "python -m experiments.context_dedup", _context_dedup),
    Figure("disagreement", "5 — Correlated error / disagreement rate", "disagreement_summary",
           "python -m experiments.disagreement --pairs homo,hetero", _disagreement),
)


# --- writing -----------------------------------------------------------------

def _read(path: Path) -> list[dict[str, str]]:
    with path.open(newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def _provenance(csv_label: str, row: Row) -> str:
    return (f"{csv_label} · sha {row['run_git_sha']} · {row['run_date']} · "
            f"network {row['run_network']}")


def _nodes(rows: Sequence[Row]) -> str:
    """A sweep over N writes each row's own node count; say the range, not row one's."""
    counts = sorted({int(r["run_node_count"]) for r in rows})
    return str(counts[0]) if len(counts) == 1 else f"{counts[0]}–{counts[-1]}"


def _markdown_table(table: Table) -> list[str]:
    header, rows = table
    lines = ["| " + " | ".join(header) + " |",
             "|" + "|".join([":--"] + ["--:"] * (len(header) - 1)) + "|"]
    lines += ["| " + " | ".join(str(c) for c in row) + " |" for row in rows]
    return lines


def render(results_dir: Path, docs_dir: Path, results_label: str = "results",
           ) -> tuple[list[str], list[str]]:
    """Write every figure whose CSV exists; return (drawn, missing) names.

    `results_label` is how the CSV directory is written in the docs -- the
    path as the user gave it, never resolved, so no local home directory
    ends up in a committed file.
    """
    figures_dir = docs_dir / "figures"
    figures_dir.mkdir(parents=True, exist_ok=True)
    drawn: list[str] = []
    missing: list[str] = []
    block = [BEGIN, "", NOTICE, ""]
    for fig in FIGURES:
        path = results_dir / f"{fig.csv}.csv"
        block.append(f"### {fig.heading}")
        block.append("")
        rows = _read(path) if path.exists() else []
        if not rows:
            missing.append(fig.name)
            block += [f"Not run. `{fig.command}` writes `{results_label}/{fig.csv}.csv`.", ""]
            continue
        label = f"{results_label}/{fig.csv}.csv"
        svg, table = fig.draw(rows, _provenance(label, rows[0]))
        (figures_dir / f"{fig.name}.svg").write_text(svg, encoding="utf-8", newline="\n")
        drawn.append(fig.name)
        r0 = rows[0]
        block += [f"![{fig.heading}](figures/{fig.name}.svg)", ""]
        block += _markdown_table(table)
        block += ["", (f"`{label}` · sha `{r0['run_git_sha']}` · {r0['run_date']} · "
                       f"network `{r0['run_network']}` · {_nodes(rows)} nodes · "
                       f"seed {r0['run_seed']}"), ""]
    block.append(END)
    _splice(docs_dir / "RESULTS.md", "\n".join(block))
    return drawn, missing


def _splice(path: Path, block: str) -> None:
    """Replace the generated block, leaving the hand-written prose around it."""
    text = path.read_text(encoding="utf-8") if path.exists() else ""
    start = text.find(BEGIN)
    end = text.find(END)
    if start == -1 or end == -1 or end < start:
        raise ValueError(f"{path} has no {BEGIN!r} ... {END!r} block to regenerate")
    path.write_text(text[:start] + block + text[end + len(END):], encoding="utf-8",
                    newline="\n")


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="experiments.plots", description=__doc__.split("\n")[0])
    parser.add_argument("--results-dir", default=None,
                        help=f"where the summary CSVs are (default {harness.RESULTS_DIR})")
    parser.add_argument("--docs-dir", default=None, help=f"default {DOCS_DIR}")
    args = parser.parse_args(argv)
    results_dir = Path(args.results_dir) if args.results_dir else harness.RESULTS_DIR
    docs_dir = Path(args.docs_dir) if args.docs_dir else DOCS_DIR
    drawn, missing = render(results_dir, docs_dir, args.results_dir or "results")
    print(f"drew {len(drawn)}: {', '.join(drawn) or '-'} -> {docs_dir / 'figures'}", file=sys.stderr)
    if missing:
        print(f"not run: {', '.join(missing)}", file=sys.stderr)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
